CREATE TABLE payroll_snapshots(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,month TEXT NOT NULL,snapshot_token TEXT NOT NULL,lesson_id TEXT NOT NULL,teacher_id TEXT NOT NULL,rate INTEGER NOT NULL CHECK(typeof(rate)='integer'),rate_basis TEXT NOT NULL,quantity REAL NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer'),lesson_json TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,lesson_id) REFERENCES lessons(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id));
